window.SKY_BENCHMARK_CONTENT = {"home": "<section class=\"hero\" data-ch=\"00\" data-ar=\"البداية\" data-en=\"Prologue\">\n      <div class=\"hero-bg\"></div>\n      <div class=\"hero-star\"><svg viewBox=\"213 218 116 116\">\n          <use href=\"#star\" fill=\"#fff\" />\n        </svg></div>\n      <div class=\"hero-in wrap\">\n        <div class=\"eyebrow fade\"><span class=\"ar\">سكاي ري</span><span class=\"en\">Sky Re</span><i></i><span\n            class=\"ar\">وكالة اكتتاب لإعادة التأمين</span><span class=\"en\">Reinsurance MGA</span><i></i><span\n            class=\"ar\">الرياض</span><span class=\"en\">Riyadh</span></div>\n        <h1>\n          <span class=\"ar\"><span class=\"w\" style=\"--i:0\">حين</span> <span class=\"w\" style=\"--i:1\">تكتمل</span> <span\n              class=\"w\" style=\"--i:2\">الشراكة</span><br><span class=\"w\" style=\"--i:3\">يولد</span> <span class=\"w\"\n              style=\"--i:4\"><em>النجم.</em></span></span>\n          <span class=\"en\"><span class=\"w\" style=\"--i:0\">When</span> <span class=\"w\" style=\"--i:1\">partnership</span>\n            <span class=\"w\" style=\"--i:2\">is</span> <span class=\"w\" style=\"--i:3\">complete,</span><br><span class=\"w\"\n              style=\"--i:4\">a</span> <span class=\"w\" style=\"--i:5\"><em>star</em></span> <span class=\"w\"\n              style=\"--i:6\">is</span> <span class=\"w\" style=\"--i:7\">born.</span></span>\n        </h1>\n        <div class=\"hero-row\">\n          <p class=\"lead fade\"><span class=\"ar\">هذه ليست مجرد هوية بصرية؛ إنها قصة هلالين متقابلين يلتقيان، فيولد من\n              لقائهما نجمٌ جديد يهتدي به السوق. تعرّف على سكاي ري، وعلى المعنى الكامن خلف كل منحنى في\n              شعارها.</span><span class=\"en\">This is not just a visual identity. It is the story of two opposing\n              crescents that meet — and from their meeting, a new guiding star is born. Discover Sky Re, and the meaning\n              behind every curve of its mark.</span></p>\n          <a href=\"#company\" class=\"scroll-cue fade\"><span class=\"ar\">مرّر لتبدأ الرحلة</span><span class=\"en\">Scroll to\n              begin</span><span class=\"ln\"></span></a>\n        </div>\n      </div>\n    </section><div class=\"promise\" aria-hidden=\"true\">\n      <div class=\"ticker\">\n        <span><span class=\"en\">Elevating Capacity, Empowering Regional Growth</span><span class=\"ar\">نرتقي بالطاقة\n            الاكتتابية · ونمكّن النمو الإقليمي</span><i></i><span class=\"en\">Precision in Underwriting</span><span\n            class=\"ar\">دقةٌ في الاكتتاب</span><i></i><span class=\"en\">Authority in Protection</span><span\n            class=\"ar\">سلطةٌ في الحماية</span><i></i><span class=\"en\">Partnership in Scale</span><span class=\"ar\">شراكةٌ\n            واسعة النطاق</span><i></i><span class=\"en\">Elevating Capacity, Empowering Regional Growth</span><span\n            class=\"ar\">نرتقي بالطاقة الاكتتابية · ونمكّن النمو الإقليمي</span><i></i><span class=\"en\">Precision in\n            Underwriting</span><span class=\"ar\">دقةٌ في الاكتتاب</span><i></i><span class=\"en\">Authority in\n            Protection</span><span class=\"ar\">سلطةٌ في الحماية</span><i></i><span class=\"en\">Partnership in\n            Scale</span><span class=\"ar\">شراكةٌ واسعة النطاق</span><i></i></span>\n        <span><span class=\"en\">Elevating Capacity, Empowering Regional Growth</span><span class=\"ar\">نرتقي بالطاقة\n            الاكتتابية · ونمكّن النمو الإقليمي</span><i></i><span class=\"en\">Precision in Underwriting</span><span\n            class=\"ar\">دقةٌ في الاكتتاب</span><i></i><span class=\"en\">Authority in Protection</span><span\n            class=\"ar\">سلطةٌ في الحماية</span><i></i><span class=\"en\">Partnership in Scale</span><span class=\"ar\">شراكةٌ\n            واسعة النطاق</span><i></i><span class=\"en\">Elevating Capacity, Empowering Regional Growth</span><span\n            class=\"ar\">نرتقي بالطاقة الاكتتابية · ونمكّن النمو الإقليمي</span><i></i><span class=\"en\">Precision in\n            Underwriting</span><span class=\"ar\">دقةٌ في الاكتتاب</span><i></i><span class=\"en\">Authority in\n            Protection</span><span class=\"ar\">سلطةٌ في الحماية</span><i></i><span class=\"en\">Partnership in\n            Scale</span><span class=\"ar\">شراكةٌ واسعة النطاق</span><i></i></span>\n      </div>\n    </div><section class=\"sec\" id=\"company\" data-ch=\"01\" data-ar=\"الشركة\" data-en=\"The Company\">\n      <div class=\"wrap\">\n        <div class=\"company-grid\">\n          <div>\n            <div class=\"chap rv\"><span class=\"n\">01</span><span class=\"l\"></span><span class=\"ar\">الشركة</span><span\n                class=\"en\">The Company</span></div>\n            <h2 class=\"big rv\"><span class=\"ar\">وكالة إعادة تأمين رائدة، من <em>قلب الرياض</em></span><span class=\"en\">A\n                premier reinsurance MGA, from the <em>heart of Riyadh</em></span></h2>\n            <p class=\"lead rv\" style=\"--d:.1s;margin-top:28px\"><span class=\"ar\">سكاي ري وكالة اكتتاب عامة مرخّصة في مجال\n                إعادة التأمين (MGA)، يقع مقرها الرئيسي في الرياض، وتركّز على الاكتتاب، وإدارة المخاطر، وتوفير الطاقة\n                الاكتتابية لشركات التأمين.</span><span class=\"en\">Sky Re is a licensed reinsurance Managing General\n                Agency headquartered in Riyadh, Saudi Arabia — focused on underwriting, risk management and capacity\n                placement for insurers.</span></p>\n          </div>\n          <div class=\"facts\">\n            <div class=\"fact rv\" style=\"--d:.05s\"><span class=\"k\">I</span>\n              <div>\n                <h4><span class=\"ar\">سياق السوق</span><span class=\"en\">Market Context</span></h4>\n                <p><span class=\"ar\">نعمل في قطاع مالي متميّز وعالي التنظيم، في قلب التحوّل الاقتصادي لرؤية السعودية\n                    2030، ضمن سوق تأمين وإعادة تأمين يتسارع نضجه.</span><span class=\"en\">Operating in a highly\n                    regulated, premium financial sector at the heart of Saudi Vision 2030's economic transformation —\n                    within a rapidly maturing insurance &amp; reinsurance landscape.</span></p>\n              </div>\n            </div>\n            <div class=\"fact rv\" style=\"--d:.15s\"><span class=\"k\">II</span>\n              <div>\n                <h4><span class=\"ar\">الفرصة</span><span class=\"en\">The Opportunity</span></h4>\n                <p><span class=\"ar\">مدّ الجسر بين المعرفة العميقة بالسوق المحلي وأفضل الممارسات الدولية.</span><span\n                    class=\"en\">Bridging local market knowledge with international best practices.</span></p>\n              </div>\n            </div>\n            <div class=\"fact rv\" style=\"--d:.25s\"><span class=\"k\">III</span>\n              <div>\n                <h4><span class=\"ar\">موقعنا</span><span class=\"en\">Our Position</span></h4>\n                <p><span class=\"ar\">الشريك المتمرّس والموثوق الذي يجمع بين التميّز التنظيمي والخبرة ذات الرؤية\n                    المستقبلية.</span><span class=\"en\">The sophisticated, trusted partner that combines regulatory\n                    excellence with forward-thinking expertise.</span></p>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- WR:BEGIN — Who We Are -->\n        <div class=\"wr-block\" id=\"who-we-are\">\n          <div class=\"wr-head\">\n            <div class=\"wr-k rv\"><span class=\"l\"></span><span class=\"ar\">من نحن</span><span class=\"en\">Who We Are</span>\n            </div>\n            <h3 class=\"wr-h rv\"><span class=\"ar\">نربط <em>الطاقة الاكتتابية الدولية</em> بالخبرة المحلية</span><span\n                class=\"en\">Connecting <em>global capacity</em> with local expertise</span></h3>\n            <p class=\"lead rv\" style=\"--d:.1s\"><span class=\"ar\">سكاي ري وكيل إعادة تأمين يعمل نيابةً عن معيدي التأمين في\n                الاكتتاب في مخاطر الممتلكات والحوادث التجارية المعقّدة — بما فيها الممتلكات والهندسة والحوادث والطاقة\n                والبحري — فيوزّع المخاطر محليًا بخبرة اكتتابية معزّزة، ويجلب الطاقة الاكتتابية الدولية عبر شبكة\n                متفوّقة.</span><span class=\"en\">SKY RE is a Reinsurance Agent that acts on behalf of Reinsurers to\n                underwrite complex commercial P&amp;C risks — including Property, Engineering, Casualty, Energy and\n                Marine — distributing risks locally through enhanced underwriting expertise, and bringing international\n                capacity through a superior network.</span></p>\n            <ul class=\"wr-sectors rv\" style=\"--d:.18s\">\n              <li><span class=\"ar\">الممتلكات</span><span class=\"en\">Property</span></li>\n              <li><span class=\"ar\">الهندسة</span><span class=\"en\">Engineering</span></li>\n              <li><span class=\"ar\">الحوادث</span><span class=\"en\">Casualty</span></li>\n              <li><span class=\"ar\">الطاقة</span><span class=\"en\">Energy</span></li>\n              <li><span class=\"ar\">البحري</span><span class=\"en\">Marine</span></li>\n            </ul>\n          </div>\n          <div class=\"who-stage rv\" style=\"--d:.1s\" tabindex=\"0\" role=\"img\"\n            aria-label=\"Sky Re connects international reinsurance capacity with local underwriting expertise\">\n            <canvas class=\"who-cv\" aria-hidden=\"true\"></canvas>\n            <svg class=\"who-sym\" viewBox=\"0 0 543.4 543.4\" aria-hidden=\"true\">\n              <g class=\"wA\">\n                <use href=\"#s0\" class=\"o\" />\n                <use href=\"#s1\" class=\"i\" />\n              </g>\n              <g class=\"wB\">\n                <use href=\"#s2\" class=\"o\" />\n                <use href=\"#s3\" class=\"i\" />\n              </g>\n              <use href=\"#star\" class=\"st\" />\n            </svg>\n            <div class=\"who-lab g\"><span class=\"k\">Global</span><span class=\"t\"><span class=\"ar\">الطاقة الاكتتابية\n                  الدولية</span><span class=\"en\">Global Capacity</span></span><span class=\"s\"><span class=\"ar\">معيدو\n                  تأمين دوليون عبر شبكة متفوّقة</span><span class=\"en\">International reinsurers through a superior\n                  network</span></span></div>\n            <div class=\"who-lab l\"><span class=\"k\">Local</span><span class=\"t\"><span class=\"ar\">الخبرة\n                  المحلية</span><span class=\"en\">Local Expertise</span></span><span class=\"s\"><span class=\"ar\">اكتتاب\n                  معزّز وتوزيع للمخاطر في السوق السعودي</span><span class=\"en\">Enhanced underwriting, distributing risk\n                  in the Saudi market</span></span></div>\n            <div class=\"who-lab c\"><b>SKY RE</b><span>MGA</span></div>\n            <p class=\"wr-sr\"><span class=\"ar\">رسم تفاعلي: تتدفّق الطاقة الاكتتابية من معيدي التأمين الدوليين عبر سكاي ري\n                إلى السوق المحلي، وتتدفّق المخاطر في الاتجاه المعاكس.</span><span class=\"en\">Interactive illustration:\n                capacity flows from international reinsurers through Sky Re to the local market, while risk flows in the\n                opposite direction.</span></p>\n          </div>\n          <div class=\"who-cap rv\">\n            <div class=\"lg\"><span><i></i><span class=\"ar\">الطاقة الاكتتابية</span><span\n                  class=\"en\">Capacity</span></span><span><i class=\"s\"></i><span class=\"ar\">المخاطر</span><span\n                  class=\"en\">Risk</span></span></div>\n            <span class=\"hint\"><span class=\"hint-fine\"><span class=\"ar\">حرّك المؤشّر بين الجانبين</span><span\n                  class=\"en\">Move across the two sides</span></span><span class=\"hint-touch\"><span class=\"ar\">مرّر أو\n                  المس الرسم</span><span class=\"en\">Scroll or touch the illustration</span></span></span>\n          </div>\n        </div>\n\n        <!-- WR — Our Role -->\n        <div class=\"wr-block\" id=\"our-role\">\n          <div class=\"wr-head wr-head--row\">\n            <div>\n              <div class=\"wr-k rv\"><span class=\"l\"></span><span class=\"ar\">دورنا</span><span class=\"en\">Our Role</span>\n              </div>\n              <h3 class=\"wr-h rv\"><span class=\"ar\">ثمانية أدوار… <em>نصنع بها القيمة</em></span><span class=\"en\">Eight\n                  ways we <em>create value</em></span></h3>\n            </div>\n            <p class=\"lead rv\" style=\"--d:.1s\"><span class=\"ar\">من الاكتتاب المتخصص حتى وفورات الحجم — كيف تخدم سكاي ري\n                شركات التأمين ومعيدي التأمين عبر دورة حياة المخاطر.</span><span class=\"en\">From specialized underwriting\n                to economies of scale — how SKY RE serves insurers and reinsurers across the life of a risk.</span></p>\n          </div>\n          <div class=\"role-grid\">\n            <article class=\"role rv\" data-k=\"shield\" tabindex=\"0\">\n              <div class=\"role-top\"><span class=\"num\">01</span><span class=\"tag\"><span class=\"ar\">الخبرة</span><span\n                    class=\"en\">Expertise</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">الاكتتاب المتخصص</span><span class=\"en\">Specialized Underwriting</span></h4>\n              <p><span class=\"ar\">قدرات اكتتاب متخصصة للمخاطر المعقّدة والنوعية.</span><span class=\"en\">Specialized\n                  underwriting capabilities for complex and niche risks.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"modules\" tabindex=\"0\" style=\"--d:.06s\">\n              <div class=\"role-top\"><span class=\"num\">02</span><span class=\"tag\"><span class=\"ar\">الابتكار</span><span\n                    class=\"en\">Innovation</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">حلول مصمّمة حسب الحاجة</span><span class=\"en\">Tailored Solutions</span></h4>\n              <p><span class=\"ar\">تطوير منتجات مبتكرة مصمّمة وفق احتياجات العملاء.</span><span class=\"en\">Tailored and\n                  innovative product offerings.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"radar\" tabindex=\"0\" style=\"--d:.12s\">\n              <div class=\"role-top\"><span class=\"num\">03</span><span class=\"tag\"><span class=\"ar\">الرؤية</span><span\n                    class=\"en\">Insight</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">تقييم المخاطر</span><span class=\"en\">Risk Assessment</span></h4>\n              <p><span class=\"ar\">خدمات تقييم المخاطر لدعم اتخاذ قرارات أفضل.</span><span class=\"en\">Risk assessment\n                  services that improve decision-making.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"path\" tabindex=\"0\" style=\"--d:.18s\">\n              <div class=\"role-top\"><span class=\"num\">04</span><span class=\"tag\"><span class=\"ar\">الخدمة</span><span\n                    class=\"en\">Service</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">دعم ما بعد الإصدار</span><span class=\"en\">Post-Bind Support</span></h4>\n              <p><span class=\"ar\">تبسيط الدعم والتنسيق بعد إصدار الوثيقة لتسويات أسرع وأكثر كفاءة.</span><span\n                  class=\"en\">Streamlined post-bind support and coordination for faster, more efficient\n                  resolutions.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"pool\" tabindex=\"0\">\n              <div class=\"role-top\"><span class=\"num\">05</span><span class=\"tag\"><span class=\"ar\">التوازن</span><span\n                    class=\"en\">Balance</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">تنويع المخاطر</span><span class=\"en\">Risk Diversification</span></h4>\n              <p><span class=\"ar\">تيسير تجميع المخاطر وتنويعها.</span><span class=\"en\">Facilitating risk pooling and\n                  diversification.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"network\" tabindex=\"0\" style=\"--d:.06s\">\n              <div class=\"role-top\"><span class=\"num\">06</span><span class=\"tag\"><span class=\"ar\">التوزيع</span><span\n                    class=\"en\">Distribution</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">التوزيع المحلي للمخاطر</span><span class=\"en\">Local Risk Distribution</span></h4>\n              <p><span class=\"ar\">تقليل الاعتماد على إعادة التأمين الخارجية عبر توزيع أفضل للمخاطر.</span><span\n                  class=\"en\">Reducing reliance on external reinsurance by better distributing risk.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"align\" tabindex=\"0\" style=\"--d:.12s\">\n              <div class=\"role-top\"><span class=\"num\">07</span><span class=\"tag\"><span class=\"ar\">الكفاءة</span><span\n                    class=\"en\">Efficiency</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">الكفاءة التشغيلية</span><span class=\"en\">Operational Efficiency</span></h4>\n              <p><span class=\"ar\">تحويل تكاليف الاكتتاب الثابتة إلى تكاليف متغيّرة عبر الإسناد الخارجي.</span><span\n                  class=\"en\">Converting fixed underwriting costs to variable costs via outsourcing.</span></p>\n            </article>\n            <article class=\"role rv\" data-k=\"scale\" tabindex=\"0\" style=\"--d:.18s\">\n              <div class=\"role-top\"><span class=\"num\">08</span><span class=\"tag\"><span class=\"ar\">الحجم</span><span\n                    class=\"en\">Scale</span></span></div><canvas class=\"role-cv\" aria-hidden=\"true\"></canvas>\n              <h4><span class=\"ar\">وفورات الحجم</span><span class=\"en\">Economies of Scale</span></h4>\n              <p><span class=\"ar\">الاستفادة من وفورات الحجم للحصول على شروط إعادة تأمين أفضل.</span><span\n                  class=\"en\">Leveraging economies of scale for better reinsurance terms.</span></p>\n            </article>\n          </div>\n        </div>\n        <!-- WR:END -->\n        <div class=\"vision rv\">\n          <svg class=\"ghost\" viewBox=\"0 0 543.4 543.4\" aria-hidden=\"true\">\n            <use href=\"#symbol\" />\n          </svg>\n          <div class=\"vision-in\">\n            <div>\n              <div class=\"year\"><span class=\"count\" data-to=\"2030\">2030</span></div>\n              <div class=\"year-l\"><span class=\"ar\">رؤية سكاي ري</span><span class=\"en\">Sky Re Vision</span></div>\n            </div>\n            <div>\n              <h3><span class=\"ar\">أن نصبح وكالة الاكتتاب الرائدة في تأمين الممتلكات والحوادث (المباشر والاختياري) في\n                  المملكة العربية السعودية بحلول عام 2030.</span><span class=\"en\">To become a leading Property &amp;\n                  Casualty (Direct &amp; Facultative) MGA in the Kingdom of Saudi Arabia by 2030.</span></h3>\n              <div class=\"vtriad\">\n                <div><b><span class=\"ar\">لعملائنا</span><span class=\"en\">For Our Clients</span></b>\n                  <p><span class=\"ar\">حلول إعادة تأمين متنوّعة ومصمّمة حسب الحاجة.</span><span class=\"en\">Diversified\n                      and tailored reinsurance solutions.</span></p>\n                </div>\n                <div><b><span class=\"ar\">لمزوّدي الطاقة الاكتتابية</span><span class=\"en\">For Capacity\n                      Providers</span></b>\n                  <p><span class=\"ar\">نموّ استثنائي ومستدام في نتائج الاكتتاب.</span><span class=\"en\">Exceptional and\n                      sustainable underwriting growth.</span></p>\n                </div>\n                <div><b><span class=\"ar\">لمساهمينا</span><span class=\"en\">For Shareholders</span></b>\n                  <p><span class=\"ar\">خلق قيمة طويلة الأمد.</span><span class=\"en\">Long-term value creation.</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>", "about": "<section id=\"symbol-story\" data-ch=\"02\" data-ar=\"الرمز\" data-en=\"The Symbol\">\n      <div class=\"wrap story-head\">\n        <div class=\"chap rv\"><span class=\"n\">02</span><span class=\"l\"></span><span class=\"ar\">قصة الرمز</span><span\n            class=\"en\">The Story of the Symbol</span></div>\n        <h1 class=\"big rv\"><span class=\"ar\">هلالان متقابلان… <em>ونجمٌ يولد</em> من اللقاء</span><span class=\"en\">Two\n            opposing crescents — <em>and a star</em> born of their joining</span></h1>\n      </div>\n      <div class=\"wrap\">\n        <div class=\"story\">\n          <div class=\"stage-wrap\">\n            <div class=\"stage\" id=\"stage\" data-step=\"0\">\n              <svg viewBox=\"-80 -80 703.4 703.4\" aria-hidden=\"true\">\n                <g class=\"grid-bg\">\n                  <rect x=\"0\" y=\"0\" width=\"543.4\" height=\"543.4\" />\n                  <line x1=\"0\" y1=\"0\" x2=\"543.4\" y2=\"543.4\" />\n                  <line x1=\"543.4\" y1=\"0\" x2=\"0\" y2=\"543.4\" />\n                  <circle cx=\"271.06\" cy=\"275.36\" r=\"300\" />\n                </g>\n                <g class=\"paths\">\n                  <line pathLength=\"1\" x1=\"-70\" y1=\"-66\" x2=\"236\" y2=\"240\" />\n                  <line pathLength=\"1\" x1=\"613\" y1=\"-66\" x2=\"306\" y2=\"240\" />\n                  <line pathLength=\"1\" x1=\"613\" y1=\"617\" x2=\"306\" y2=\"310\" />\n                  <line pathLength=\"1\" x1=\"-70\" y1=\"617\" x2=\"236\" y2=\"310\" />\n                </g>\n                <g>\n                  <circle class=\"ring\" cx=\"271.06\" cy=\"275.36\" r=\"60\" />\n                  <circle class=\"ring\" cx=\"271.06\" cy=\"275.36\" r=\"60\" />\n                  <circle class=\"ring\" cx=\"271.06\" cy=\"275.36\" r=\"60\" />\n                </g>\n                <circle class=\"halo\" cx=\"271.06\" cy=\"275.36\" r=\"170\" fill=\"url(#haloG)\" />\n                <g class=\"gA\">\n                  <use href=\"#s0\" class=\"o\" />\n                  <use href=\"#s1\" class=\"i\" />\n                </g>\n                <g class=\"gB\">\n                  <use href=\"#s2\" class=\"o\" />\n                  <use href=\"#s3\" class=\"i\" />\n                </g>\n                <circle class=\"flash\" cx=\"271.06\" cy=\"275.36\" r=\"30\" />\n                <use href=\"#star\" class=\"star\" filter=\"url(#glow)\" />\n              </svg>\n              <div class=\"lab labA\"><i></i><span><b class=\"en\">Global Reach · Offshore</b><b class=\"ar\">الامتداد\n                    العالمي</b></span></div>\n              <div class=\"lab labB\"><i></i><span><b class=\"en\">Local Authority · Onshore</b><b class=\"ar\">السلطة\n                    المحلية</b></span></div>\n              <div class=\"lab labS\"><i></i><span><b class=\"en\">Sky Re</b><b class=\"ar\">سكاي ري</b></span></div>\n            </div>\n          </div>\n          <div class=\"steps\">\n            <div class=\"step\" data-step=\"0\">\n              <div class=\"step-card\">\n                <div class=\"sn\">01 / 06</div>\n                <h3><span class=\"ar\">الشكل</span><span class=\"en\">The Form</span></h3>\n                <p><span class=\"ar\">يتكوّن الشعار من هلالين متناميين متقابلين. وحين يلتقيان، تُشكّل عملية الالتقاء ذاتها\n                    نجمًا؛ فالنجم ليس عنصرًا مرسومًا بذاته، بل هو النتيجة الطبيعية لاكتمال الشراكة.</span><span\n                    class=\"en\">The mark is formed by two opposing waxing crescents. When they join, the act of joining\n                    itself shapes a star. The star is an emergent form — the natural result of a partnership\n                    completed.</span></p>\n                <span class=\"tag\"><span class=\"ar\">منظور إعادة التأمين: تقاسم المخاطر والعوائد</span><span\n                    class=\"en\">Reinsurance perspective · sharing risks &amp; rewards</span></span>\n              </div>\n            </div>\n            <div class=\"step\" data-step=\"1\">\n              <div class=\"step-card\">\n                <div class=\"sn\">02 / 06</div>\n                <h3><span class=\"ar\">الهلال العلوي<br><small class=\"muted\"\n                      style=\"font-size:.55em;font-weight:500\">الامتداد العالمي للسوق (Offshore)</small></span><span\n                    class=\"en\">The Upper Crescent<br><small class=\"muted\" style=\"font-size:.5em;font-weight:400\">Global\n                      Market Reach (Offshore)</small></span></h3>\n                <p><span class=\"ar\">يمثّل الطاقة الاكتتابية الدولية، وشبكات الاكتتاب العالمية، ورأس المال الخارجي،\n                    والامتداد المؤسسي الذي تجلبه سكاي ري إلى المملكة.</span><span class=\"en\">It represents international\n                    capacity, global underwriting networks, offshore capital, and the institutional reach that Sky Re\n                    brings into the Kingdom.</span></p>\n              </div>\n            </div>\n            <div class=\"step\" data-step=\"2\">\n              <div class=\"step-card\">\n                <div class=\"sn\">03 / 06</div>\n                <h3><span class=\"ar\">الهلال السفلي<br><small class=\"muted\"\n                      style=\"font-size:.55em;font-weight:500\">السلطة المحلية (Onshore) ومظلّة\n                      الحماية</small></span><span class=\"en\">The Downward Crescent<br><small class=\"muted\"\n                      style=\"font-size:.5em;font-weight:400\">Local Authority (Onshore) &amp; Protection\n                      Canopy</small></span></h3>\n                <p><span class=\"ar\">يمثّل الجانب المحلي من الشراكة، ويحمل أربعة معانٍ جوهرية:</span><span class=\"en\">It\n                    represents the onshore side of the partnership and carries four essential meanings:</span></p>\n                <div class=\"chips\">\n                  <div><b>01</b><span class=\"ar\">البصيرة الإقليمية</span><span class=\"en\">Regional insight</span></div>\n                  <div><b>02</b><span class=\"ar\">التفاعل التنظيمي الاستباقي</span><span class=\"en\">Proactive regulatory\n                      engagement</span></div>\n                  <div><b>03</b><span class=\"ar\">الدقّة في الاكتتاب</span><span class=\"en\">Precision in\n                      underwriting</span></div>\n                  <div><b>04</b><span class=\"ar\">بنية حماية للسوق المحلي</span><span class=\"en\">Protective structure for\n                      the local market</span></div>\n                </div>\n              </div>\n            </div>\n            <div class=\"step\" data-step=\"3\">\n              <div class=\"step-card\">\n                <div class=\"sn\">04 / 06</div>\n                <h3><span class=\"ar\">لحظة الالتقاء</span><span class=\"en\">The Moment of Joining</span></h3>\n                <p><span class=\"ar\">أهم حدث في الشعار ليس الهلالين منفردين، بل اللحظة الدقيقة التي يلتقيان فيها. في تلك\n                    اللحظة تصبح الشراكة حقيقة؛ وكل ما يهم — النجم، والهداية، والبنية المكتملة — يولد من هذا\n                    اللقاء.</span><span class=\"en\">The most important event in the mark is not either crescent alone,\n                    but the precise moment they join. That moment is the partnership becoming real. Everything that\n                    matters — the star, the guidance, the completed structure — is born from the join.</span></p>\n              </div>\n            </div>\n            <div class=\"step\" data-step=\"4\">\n              <div class=\"step-card\">\n                <div class=\"sn\">05 / 06</div>\n                <h3><span class=\"ar\">النجم المنبثق — سكاي ري</span><span class=\"en\">The Emergent Star — Sky Re</span>\n                </h3>\n                <p><span class=\"ar\">في اللحظة التي يكتمل فيها التقاء الهلالين، تُطلق الشراكة نفسها نجمًا هاديًا جديدًا:\n                    سكاي ري. ليس عنصرًا مصمّمًا بمعزل عن غيره، بل الأثر المرئي لالتقاءٍ ناجح بين الامتداد العالمي\n                    والسلطة المحلية والحماية.</span><span class=\"en\">At the exact moment the crescents join, the\n                    partnership itself gives rise to a new guiding star — Sky Re. Not a separately designed element, but\n                    the visible result of a successful union between Global Market Reach and Local Authority &amp;\n                    Protection.</span></p>\n              </div>\n            </div>\n            <div class=\"step\" data-step=\"5\">\n              <div class=\"step-card\">\n                <div class=\"sn\">06 / 06</div>\n                <h3><span class=\"ar\">المسار البصري</span><span class=\"en\">The Optical Pathway</span></h3>\n                <p><span class=\"ar\">تنتقل العين من الهلالين الخارجيين إلى النجم في المركز، ثم تتّسع من جديد — تمامًا كما\n                    تتدفّق الطاقة الاكتتابية: يلتقي الامتداد الدولي بالسلطة المحلية في المركز، ومن هذا اللقاء تتدفّق\n                    الهداية والحلول الاكتتابية إلى السوق.</span><span class=\"en\">The eye travels from the outer\n                    crescents inward to the star, then expands again — mirroring the flow of capacity: international\n                    reach and local authority meet at the centre, and from that meeting, guidance and underwriting\n                    solutions flow outward to the market.</span></p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section><section class=\"philo\" id=\"philosophy\" data-ch=\"03\" data-ar=\"الفلسفة\" data-en=\"Philosophy\">\n      <svg class=\"pat\" aria-hidden=\"true\">\n        <defs>\n          <pattern id=\"patA\" width=\"54\" height=\"54\" patternUnits=\"userSpaceOnUse\">\n            <use href=\"#s0\" transform=\"translate(2 4) scale(.085)\" fill=\"#87a7c6\" />\n            <use href=\"#s0\" transform=\"translate(29 31) scale(.085)\" fill=\"#947b4c\" />\n          </pattern>\n        </defs>\n        <rect width=\"100%\" height=\"100%\" fill=\"url(#patA)\" />\n      </svg>\n      <div class=\"wrap\">\n        <div class=\"chap rv\" style=\"justify-content:center\"><span class=\"n\">03</span><span class=\"l\"></span><span\n            class=\"ar\">الفلسفة الجوهرية</span><span class=\"en\">Core Philosophy</span><span class=\"l\"></span></div>\n        <span class=\"q-mark rv\">“</span>\n        <blockquote class=\"rv\" style=\"--d:.1s\">\n          <span class=\"ar\"><strong>سكاي ري</strong> لا تقف خارج الشراكة… <span class=\"soft\">إنها الثمرة الحيّة</span>\n            لاكتمالها.</span>\n          <span class=\"en\"><strong>Sky Re</strong> does not stand outside the partnership. <span class=\"soft\">It is the\n              living result</span> of the partnership being completed.</span>\n        </blockquote>\n        <p class=\"lead rv\" style=\"--d:.2s\"><span class=\"ar\">التقاء الامتداد العالمي بالسلطة المحلية والحماية يصنع سكاي\n            ري بشكل طبيعي — النجم الهادي الجديد الذي ينبثق من شراكةٍ قوامها تقاسم المخاطر والعوائد.</span><span\n            class=\"en\">The joining of Global Market Reach with Local Authority and Protection naturally creates Sky Re —\n            the new guiding star that emerges from a partnership of sharing risks and rewards.</span></p>\n        <div class=\"sig rv\" style=\"--d:.3s\"><span class=\"ar\">رمزية سكاي ري · نسخة نهائية معتمدة</span><span\n            class=\"en\">Sky Re Symbolism · Final &amp; Locked</span></div>\n      </div>\n    </section><section class=\"sec\" id=\"dimensions\" data-ch=\"04\" data-ar=\"أبعاد أعمق\" data-en=\"Deeper Dimensions\"\n      style=\"padding-top:clamp(60px,8vw,120px)\">\n      <div class=\"wrap\">\n        <div class=\"chap rv\"><span class=\"n\">04</span><span class=\"l\"></span><span class=\"ar\">أبعاد أعمق</span><span\n            class=\"en\">Deeper &amp; Subtle Dimensions</span></div>\n        <h2 class=\"big rv\"><span class=\"ar\">ما وراء المعنى الأول… <em>طبقاتٌ</em> تُثري العلامة</span><span\n            class=\"en\">Beyond the first reading — <em>layers</em> that enrich the brand</span></h2>\n        <div class=\"dims\">\n          <article class=\"dim rv\">\n            <span class=\"num\">01</span>\n            <div class=\"ill\"><svg class=\"mini m-join\" viewBox=\"-110 -110 763.4 763.4\">\n                <g class=\"a\">\n                  <use href=\"#s0\" class=\"o\" />\n                  <use href=\"#s1\" class=\"i\" />\n                </g>\n                <g class=\"b\">\n                  <use href=\"#s2\" class=\"o\" />\n                  <use href=\"#s3\" class=\"i\" />\n                </g>\n                <use href=\"#star\" class=\"st\" />\n              </svg></div>\n            <h4><span class=\"ar\">الالتقاء… اللحظة الحاسمة</span><span class=\"en\">The Act of Joining as the Critical\n                Moment</span></h4>\n            <p><span class=\"ar\">أهم ما في الشعار ليس الهلالين، بل لحظة التقائهما؛ عندها تصبح الشراكة حقيقة، ومنها يولد\n                كل شيء.</span><span class=\"en\">What matters most is not the individual crescents, but the precise moment\n                they join — the partnership becoming real. Everything is born from the join.</span></p>\n          </article>\n          <article class=\"dim rv\" style=\"--d:.1s\">\n            <span class=\"num\">02</span>\n            <div class=\"ill\"><svg class=\"m-canopy\" viewBox=\"0 0 200 200\">\n                <path class=\"ln dome\" pathLength=\"1\" d=\"M30 128 A70 70 0 0 1 170 128\" />\n                <line class=\"ln\" x1=\"22\" y1=\"150\" x2=\"178\" y2=\"150\" opacity=\".35\" />\n                <g class=\"rise\">\n                  <path class=\"lg\" d=\"M86 120 L100 106 L114 120\" />\n                </g>\n                <g class=\"rise\">\n                  <path class=\"lg\" d=\"M86 120 L100 106 L114 120\" />\n                </g>\n                <g class=\"rise\">\n                  <path class=\"lg\" d=\"M86 120 L100 106 L114 120\" />\n                </g>\n                <circle cx=\"70\" cy=\"140\" r=\"3\" fill=\"#87a7c6\" />\n                <circle cx=\"100\" cy=\"140\" r=\"3\" fill=\"#87a7c6\" />\n                <circle cx=\"130\" cy=\"140\" r=\"3\" fill=\"#87a7c6\" />\n              </svg></div>\n            <h4><span class=\"ar\">مظلّة الحماية والارتقاء</span><span class=\"en\">Protection Canopy + Elevation</span>\n            </h4>\n            <p><span class=\"ar\">الهلال السفلي يظلّل السوق المحلي، بينما يبقى الهلالان في حالة تنامٍ وصعود: حمايةٌ لا\n                تكبح النمو، وارتقاءٌ يبقى متجذّرًا في السلطة المحلية والعناية التنظيمية.</span><span class=\"en\">The\n                downward crescent shelters the local market while both forms remain waxing — rising. Protection that\n                never suppresses growth; elevation that stays rooted in local authority and regulatory care.</span></p>\n          </article>\n          <article class=\"dim rv\" style=\"--d:.2s\">\n            <span class=\"num\">03</span>\n            <div class=\"ill\"><svg class=\"m-share\" viewBox=\"0 0 200 200\">\n                <path class=\"ln\" d=\"M100 104 L86 150 L114 150 Z\" opacity=\".5\" />\n                <g class=\"beam\">\n                  <line class=\"ln\" x1=\"34\" y1=\"100\" x2=\"166\" y2=\"100\" />\n                  <circle cx=\"40\" cy=\"82\" r=\"16\" fill=\"none\" stroke=\"#87a7c6\" stroke-width=\"1.6\" />\n                  <circle cx=\"160\" cy=\"82\" r=\"16\" fill=\"#947b4c\" />\n                  <circle cx=\"100\" cy=\"100\" r=\"4\" fill=\"#c2a56f\" />\n                </g>\n              </svg></div>\n            <h4><span class=\"ar\">تقاسم المخاطر والعوائد</span><span class=\"en\">Sharing of Risks and Rewards</span></h4>\n            <p><span class=\"ar\">يواجه الهلالان بعضهما ويُكمل كلٌّ منهما الآخر: تعرّضٌ مشترك ومنفعة مشتركة. لا يقف أي طرف\n                وحده — وهذا جوهر الشراكة الحقيقية في إعادة التأمين.</span><span class=\"en\">The crescents face and\n                complete each other: mutual exposure, mutual benefit. Neither side stands alone — the very definition of\n                true partnership in reinsurance.</span></p>\n          </article>\n          <article class=\"dim rv\">\n            <span class=\"num\">04</span>\n            <div class=\"ill\"><svg class=\"m-guide\" viewBox=\"0 0 200 200\">\n                <g class=\"rays\">\n                  <line class=\"lg\" x1=\"100\" y1=\"20\" x2=\"100\" y2=\"44\" />\n                  <line class=\"lg\" x1=\"100\" y1=\"156\" x2=\"100\" y2=\"180\" />\n                  <line class=\"lg\" x1=\"20\" y1=\"100\" x2=\"44\" y2=\"100\" />\n                  <line class=\"lg\" x1=\"156\" y1=\"100\" x2=\"180\" y2=\"100\" />\n                  <line class=\"ln\" x1=\"44\" y1=\"44\" x2=\"58\" y2=\"58\" opacity=\".6\" />\n                  <line class=\"ln\" x1=\"156\" y1=\"44\" x2=\"142\" y2=\"58\" opacity=\".6\" />\n                  <line class=\"ln\" x1=\"44\" y1=\"156\" x2=\"58\" y2=\"142\" opacity=\".6\" />\n                  <line class=\"ln\" x1=\"156\" y1=\"156\" x2=\"142\" y2=\"142\" opacity=\".6\" />\n                </g>\n                <g transform=\"translate(100 100) scale(.72) translate(-271.06 -275.36)\">\n                  <use href=\"#star\" class=\"gs\" />\n                </g>\n                <circle class=\"dot\" cx=\"30\" cy=\"40\" r=\"1.6\" />\n                <circle class=\"dot\" cx=\"170\" cy=\"60\" r=\"1.2\" style=\"animation-delay:1s\" />\n                <circle class=\"dot\" cx=\"150\" cy=\"170\" r=\"1.6\" style=\"animation-delay:2s\" />\n                <circle class=\"dot\" cx=\"40\" cy=\"160\" r=\"1.2\" style=\"animation-delay:.5s\" />\n              </svg></div>\n            <h4><span class=\"ar\">الهداية المنبثقة</span><span class=\"en\">Emergent Guidance</span></h4>\n            <p><span class=\"ar\">لا يفرض النجم نفسه من الخارج، ولا يظهر إلا حين تكتمل الشراكة. فالقيادة الحقيقية تنبع من\n                الالتقاء الناجح، لا من الطموح المنفرد.</span><span class=\"en\">The star does not impose itself from\n                outside — it appears only when the partnership is complete. Genuine leadership arises from successful\n                joining, not from solitary ambition.</span></p>\n          </article>\n          <article class=\"dim rv\" style=\"--d:.1s\">\n            <span class=\"num\">05</span>\n            <div class=\"ill\"><svg class=\"m-path\" viewBox=\"0 0 200 200\">\n                <circle class=\"r\" cx=\"100\" cy=\"100\" r=\"80\" />\n                <circle class=\"r\" cx=\"100\" cy=\"100\" r=\"80\" />\n                <circle class=\"r\" cx=\"100\" cy=\"100\" r=\"80\" />\n                <line class=\"ln in\" x1=\"20\" y1=\"20\" x2=\"88\" y2=\"88\" />\n                <line class=\"ln in\" x1=\"180\" y1=\"20\" x2=\"112\" y2=\"88\" />\n                <line class=\"ln in\" x1=\"180\" y1=\"180\" x2=\"112\" y2=\"112\" />\n                <line class=\"ln in\" x1=\"20\" y1=\"180\" x2=\"88\" y2=\"112\" />\n                <circle cx=\"100\" cy=\"100\" r=\"5\" fill=\"#c2a56f\" />\n              </svg></div>\n            <h4><span class=\"ar\">المسار البصري</span><span class=\"en\">Optical Pathway</span></h4>\n            <p><span class=\"ar\">من الأطراف إلى النجم، ثم إلى الخارج من جديد — انعكاسٌ لتدفّق الطاقة الاكتتابية: يلتقي\n                الامتداد والسلطة في المركز، ثم تتدفّق الحلول إلى السوق.</span><span class=\"en\">From the edges inward to\n                the star, then outward again — the operational flow of capacity: reach and authority meet at the centre,\n                and solutions flow out to the market.</span></p>\n          </article>\n          <article class=\"dim rv\" style=\"--d:.2s\">\n            <span class=\"num\">06</span>\n            <div class=\"ill\"><svg class=\"m-restraint\" viewBox=\"0 0 200 200\">\n                <rect class=\"ln\" x=\"30\" y=\"30\" width=\"140\" height=\"140\" opacity=\".25\" />\n                <line class=\"ln\" x1=\"100\" y1=\"22\" x2=\"100\" y2=\"178\" opacity=\".18\" />\n                <line class=\"ln\" x1=\"22\" y1=\"100\" x2=\"178\" y2=\"100\" opacity=\".18\" />\n                <circle class=\"lg arc\" pathLength=\"1\" cx=\"100\" cy=\"100\" r=\"62\" transform=\"rotate(-90 100 100)\" />\n              </svg></div>\n            <h4><span class=\"ar\">نهج الانضباط</span><span class=\"en\">Pattern of Restraint</span></h4>\n            <p><span class=\"ar\">لا زخرفة زائدة، ولا إغلاق قسري في دائرة كاملة، ولا تصادم عنيف. انضباط الهندسة يعكس\n                الانضباط المطلوب في الاكتتاب وفي التعامل التنظيمي.</span><span class=\"en\">No excess decoration, no\n                forced closure into a full circle, no aggressive collision. The discipline of the geometry mirrors the\n                discipline of underwriting and regulatory engagement.</span></p>\n          </article>\n        </div>\n      </div>\n    </section><section class=\"sec\" id=\"geometry\" data-ch=\"05\" data-ar=\"الهندسة\" data-en=\"The Geometry\" style=\"padding-top:0\">\n      <div class=\"wrap\">\n        <div class=\"geo-grid\">\n          <div class=\"geo-art\" id=\"geoArt\">\n            <svg viewBox=\"-60 -60 663.4 663.4\" aria-hidden=\"true\">\n              <defs>\n                <clipPath id=\"sq\">\n                  <rect x=\"-30\" y=\"-30\" width=\"603.4\" height=\"603.4\" />\n                </clipPath>\n              </defs>\n              <g clip-path=\"url(#sq)\">\n                <rect class=\"cl\" pathLength=\"1\" x=\"0\" y=\"0\" width=\"543.4\" height=\"543.4\" />\n                <line class=\"cl\" pathLength=\"1\" x1=\"0\" y1=\"0\" x2=\"543.4\" y2=\"543.4\" />\n                <line class=\"cl\" pathLength=\"1\" x1=\"543.4\" y1=\"0\" x2=\"0\" y2=\"543.4\" />\n                <line class=\"cl\" pathLength=\"1\" x1=\"271.06\" y1=\"-30\" x2=\"271.06\" y2=\"573\" />\n                <line class=\"cl\" pathLength=\"1\" x1=\"-30\" y1=\"275.36\" x2=\"573\" y2=\"275.36\" />\n                <circle class=\"cl\" pathLength=\"1\" cx=\"96.47\" cy=\"96.47\" r=\"185.2\" />\n                <circle class=\"cl\" pathLength=\"1\" cx=\"10.88\" cy=\"10.88\" r=\"243.9\" />\n                <circle class=\"cl\" pathLength=\"1\" cx=\"446.93\" cy=\"446.93\" r=\"185.2\" />\n                <circle class=\"cl\" pathLength=\"1\" cx=\"532.52\" cy=\"532.52\" r=\"243.9\" />\n                <circle class=\"cl g\" pathLength=\"1\" cx=\"271.06\" cy=\"275.36\" r=\"52.4\" />\n                <circle class=\"cl g\" pathLength=\"1\" cx=\"271.06\" cy=\"275.36\" r=\"140\" />\n              </g>\n              <g class=\"fillA\">\n                <use href=\"#s0\" class=\"o\" />\n                <use href=\"#s1\" class=\"i\" />\n              </g>\n              <g class=\"fillB\">\n                <use href=\"#s2\" class=\"o\" />\n                <use href=\"#s3\" class=\"i\" />\n              </g>\n              <circle class=\"pt\" cx=\"96.47\" cy=\"96.47\" r=\"4\" />\n              <circle class=\"pt\" cx=\"446.93\" cy=\"446.93\" r=\"4\" />\n              <circle class=\"pt\" cx=\"271.06\" cy=\"275.36\" r=\"4\" />\n              <text class=\"gl\" x=\"0\" y=\"-22\">1 : 1</text>\n            </svg>\n          </div>\n          <div>\n            <div class=\"chap rv\"><span class=\"n\">05</span><span class=\"l\"></span><span class=\"ar\">فلسفة\n                البناء</span><span class=\"en\">Logo Philosophy</span></div>\n            <h2 class=\"big rv\" style=\"font-size:clamp(1.9rem,3.6vw,3.3rem)\"><span class=\"ar\">قمرٌ، ونجمٌ، وأفق… في\n                <em>بنيةٍ مربّعة</em> متوازنة</span><span class=\"en\">Moon, star and horizon — within a <em>balanced\n                  square</em></span></h2>\n            <div class=\"geo-list\">\n              <div class=\"geo-item rv\"><svg class=\"ic\" viewBox=\"0 0 44 44\">\n                  <path d=\"M30 6a17 17 0 1 0 8 24A14 14 0 1 1 30 6z\" fill=\"none\" stroke=\"#c2a56f\" stroke-width=\"1.4\" />\n                </svg>\n                <div>\n                  <h4><span class=\"ar\">القمر</span><span class=\"en\">The Moon</span></h4>\n                  <p><span class=\"ar\">تستلهم الأشكال الهلالية أطوار القمر المتزايد؛ دورةٌ كاملة ومستمرة تعكس مبدأي\n                      الاستمرارية والترابط في إعادة التأمين.</span><span class=\"en\">The crescent forms reference the\n                      phases of the waxing moon — a complete, continuous cycle reflecting the principles of continuity\n                      and connection within reinsurance.</span></p>\n                </div>\n              </div>\n              <div class=\"geo-item rv\" style=\"--d:.08s\"><svg class=\"ic\" viewBox=\"0 0 44 44\">\n                  <path d=\"M22 4C24 16 28 20 40 22C28 24 24 28 22 40C20 28 16 24 4 22C16 20 20 16 22 4Z\" fill=\"none\"\n                    stroke=\"#c2a56f\" stroke-width=\"1.4\" />\n                </svg>\n                <div>\n                  <h4><span class=\"ar\">النجم</span><span class=\"en\">The Star</span></h4>\n                  <p><span class=\"ar\">في المركز، عنصرٌ محوري يوحّد ما حوله؛ يرمز إلى الثقة والاستقرار والتميّز، ونقطة\n                      ارتكاز للطمأنينة تعكس دور الشركة شريكًا موثوقًا في إدارة المخاطر.</span><span class=\"en\">At the\n                      centre, a focal element unifying the surrounding forms — trust, stability and distinction; a\n                      central point of confidence reflecting the company's role as a trusted partner in risk\n                      management.</span></p>\n                </div>\n              </div>\n              <div class=\"geo-item rv\" style=\"--d:.16s\"><svg class=\"ic\" viewBox=\"0 0 44 44\">\n                  <path d=\"M2 30 Q22 18 42 30\" fill=\"none\" stroke=\"#c2a56f\" stroke-width=\"1.4\" />\n                  <line x1=\"2\" y1=\"36\" x2=\"42\" y2=\"36\" stroke=\"#c2a56f\" stroke-width=\"1.4\" opacity=\".5\" />\n                </svg>\n                <div>\n                  <h4><span class=\"ar\">الأفق</span><span class=\"en\">The Horizon</span></h4>\n                  <p><span class=\"ar\">تكوينٌ متوازن ومتماثل يعبّر عن الاتساع والتفرّد والاستمرارية.</span><span\n                      class=\"en\">A balanced, symmetrical composition expressing expanse, individuality and\n                      continuity.</span></p>\n                </div>\n              </div>\n              <div class=\"geo-item rv\" style=\"--d:.24s\"><svg class=\"ic\" viewBox=\"0 0 44 44\">\n                  <rect x=\"6\" y=\"6\" width=\"32\" height=\"32\" fill=\"none\" stroke=\"#c2a56f\" stroke-width=\"1.4\" />\n                  <line x1=\"6\" y1=\"6\" x2=\"38\" y2=\"38\" stroke=\"#c2a56f\" stroke-width=\"1\" opacity=\".5\" />\n                </svg>\n                <div>\n                  <h4><span class=\"ar\">المربّع</span><span class=\"en\">The Square</span></h4>\n                  <p><span class=\"ar\">بنيةٌ قائمة على المربّع تعزّز التوازن والثبات والانسجام، وتجمع الحركة والصلابة في\n                      هويةٍ بصرية واحدة مميّزة.</span><span class=\"en\">A square-based structure reinforces balance,\n                      stability and harmony — bringing movement and solidity together within one distinctive\n                      identity.</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section><section class=\"sec\" id=\"foundations\" data-ch=\"06\" data-ar=\"الشعار والأسس\" data-en=\"Brand Foundations\"\n      style=\"padding-top:clamp(40px,6vw,100px)\">\n      <div class=\"wrap\">\n        <div class=\"chap rv\"><span class=\"n\">06</span><span class=\"l\"></span><span class=\"ar\">التوافق مع أسس\n            العلامة</span><span class=\"en\">Alignment with Brand Foundations</span></div>\n        <h2 class=\"big rv\"><span class=\"ar\">كل منحنى… <em>يحمل قيمة</em></span><span class=\"en\">Every curve <em>carries\n              a value</em></span></h2>\n        <div class=\"found\">\n          <div class=\"f-art\" id=\"fArt\" data-hl=\"promise\">\n            <svg viewBox=\"-80 -80 703.4 703.4\" aria-hidden=\"true\">\n              <g class=\"whole\">\n                <circle class=\"halo\" cx=\"271.06\" cy=\"275.36\" r=\"170\" fill=\"url(#haloG)\" />\n                <g class=\"gA\">\n                  <use href=\"#s0\" class=\"o\" />\n                  <use href=\"#s1\" class=\"i\" />\n                </g>\n                <g class=\"gB\">\n                  <use href=\"#s2\" class=\"o\" />\n                  <use href=\"#s3\" class=\"i\" />\n                </g>\n                <circle class=\"jring\" cx=\"271.06\" cy=\"275.36\" r=\"70\" />\n                <use href=\"#star\" class=\"star\" filter=\"url(#glow)\" />\n              </g>\n            </svg>\n          </div>\n          <div class=\"f-list\" id=\"fList\">\n            <button class=\"f-item on\" data-hl=\"promise\"><span class=\"fi\">01</span>\n              <div>\n                <h4><span class=\"ar\">وعد العلامة</span><span class=\"en\">Brand Promise</span><small><span\n                      class=\"ar\">«نرتقي بالطاقة الاكتتابية، ونمكّن النمو الإقليمي»</span><span class=\"en\">“Elevating\n                      Capacity, Empowering Regional Growth”</span></small></h4>\n                <p><span class=\"ar\">يتجسّد في الطاقة الصاعدة للهلالين المتناميين، وفي النجم الهادي الذي يظهر من\n                    التقائهما.</span><span class=\"en\">Expressed through the rising energy of the waxing forms and the\n                    guiding star that appears from their joining.</span></p>\n              </div>\n            </button>\n            <button class=\"f-item\" data-hl=\"reach\"><span class=\"fi\">02</span>\n              <div>\n                <h4><span class=\"ar\">سلطة محلية، امتداد عالمي</span><span class=\"en\">Local Authority, Global\n                    Reach</span></h4>\n                <p><span class=\"ar\">يتجسّدان مباشرةً في الهلال العلوي (الخارجي) والهلال السفلي (المحلي).</span><span\n                    class=\"en\">Directly embodied in the upper (offshore) and downward (onshore) crescents.</span></p>\n              </div>\n            </button>\n            <button class=\"f-item\" data-hl=\"partner\"><span class=\"fi\">03</span>\n              <div>\n                <h4><span class=\"ar\">شراكة متوائمة</span><span class=\"en\">Co-Aligned Partnership</span></h4>\n                <p><span class=\"ar\">تظهر جليّةً في فعل الالتقاء الذي يُنتج النجم.</span><span class=\"en\">Made visible in\n                    the act of joining that produces the star.</span></p>\n              </div>\n            </button>\n            <button class=\"f-item\" data-hl=\"discipline\"><span class=\"fi\">04</span>\n              <div>\n                <h4><span class=\"ar\">انضباط ودقّة الاكتتاب</span><span class=\"en\">Underwriting Discipline &amp;\n                    Precision</span></h4>\n                <p><span class=\"ar\">يحملهما الهلال السفلي بوصفه جزءًا من مظلّة الحماية المحلية.</span><span\n                    class=\"en\">Carried by the downward crescent as part of the onshore protection canopy.</span></p>\n              </div>\n            </button>\n            <button class=\"f-item\" data-hl=\"vision\"><span class=\"fi\">05</span>\n              <div>\n                <h4><span class=\"ar\">رؤية من علوّ شاهق</span><span class=\"en\">High-Altitude Vision</span></h4>\n                <p><span class=\"ar\">يعبّر عنها النجم الهادي المنبثق: سكاي ري.</span><span class=\"en\">Expressed through\n                    the emergent guiding star of Sky Re.</span></p>\n              </div>\n            </button>\n          </div>\n        </div>\n      </div>\n    </section><section class=\"sec light\" id=\"values\" data-ch=\"07\" data-ar=\"القيم\" data-en=\"Core Values\">\n      <div class=\"wrap\">\n        <div class=\"chap rv\"><span class=\"n\">07</span><span class=\"l\"></span><span class=\"ar\">القيم الجوهرية</span><span\n            class=\"en\">Core Brand Values</span></div>\n        <h2 class=\"big rv\" style=\"color:var(--indigo)\"><span class=\"ar\">أربع قيم… <em>تقود كل قرار</em></span><span\n            class=\"en\">Four values that <em>guide every decision</em></span></h2>\n        <div class=\"values\">\n          <div class=\"val rv\">\n            <div class=\"vn\">01</div>\n            <div>\n              <h3><span class=\"ar\">انضباط الاكتتاب</span><span class=\"en\">Underwriting Discipline</span></h3><span\n                class=\"vq\"><span class=\"ar\">«نصون الثقة بإدارةٍ دقيقة للمخاطر.»</span><span class=\"en\">“Securing trust\n                  through meticulous risk management.”</span></span>\n            </div>\n            <p><span class=\"ar\">بصفتنا وكالة اكتتاب، نحن الأمناء الموثوقون على رأس المال العالمي. نفي بهذه المسؤولية عبر\n                أعلى معايير التحليل الفني، والنزاهة الصارمة في الاكتتاب، والحوكمة الشفافة؛ نحمي ميزانيات مزوّدي الطاقة\n                الاكتتابية، ونقدّم لعملائنا أمانًا ثابتًا وموثوقًا.</span><span class=\"en\">As an MGA, we are the trusted\n                custodians of global capital. We honor this responsibility by maintaining the highest standards of\n                technical analysis, strict underwriting integrity, and transparent governance — protecting the balance\n                sheets of our capacity providers while offering consistent, reliable security to our clients.</span></p>\n          </div>\n          <div class=\"val rv\">\n            <div class=\"vn\">02</div>\n            <div>\n              <h3><span class=\"ar\">رؤية من علوّ</span><span class=\"en\">High-Altitude Vision</span></h3><span\n                class=\"vq\"><span class=\"ar\">«نستشرف مستقبل المخاطر.»</span><span class=\"en\">“Anticipating the future of\n                  risk.”</span></span>\n            </div>\n            <p><span class=\"ar\">ننظر إلى ما وراء الحدود التقليدية، ونصمّم حلولًا متقدّمة واستشرافية لمشهد المخاطر\n                المعقّدة والناشئة — من المسؤوليات السيبرانية إلى التحوّلات المناخية والمخاطر السياسية. لا نستجيب لسوق\n                اليوم فحسب، بل نهيّئ شركاءنا لحقائق الغد.</span><span class=\"en\">We look beyond conventional boundaries,\n                actively designing sophisticated, forward-thinking solutions for complex and emerging risk landscapes —\n                including cyber liabilities, climate transitions and political risk. We don't just respond to today's\n                market; we prepare our partners for tomorrow's realities.</span></p>\n          </div>\n          <div class=\"val rv\">\n            <div class=\"vn\">03</div>\n            <div>\n              <h3><span class=\"ar\">سلطة محلية، امتداد عالمي</span><span class=\"en\">Local Authority, Global Reach</span>\n              </h3><span class=\"vq\"><span class=\"ar\">«جذورٌ راسخة في الرياض، وشبكاتٌ عالمية مؤسسية.»</span><span\n                  class=\"en\">“Deep Riyadh roots, institutional global networks.”</span></span>\n            </div>\n            <p><span class=\"ar\">نمتلك فهمًا عميقًا للبيئة التنظيمية السعودية، وديناميكيات الأعمال الإقليمية، وحجم اقتصاد\n                المملكة المتحوّل. وبالجمع بين هذه الخبرة المحلية وشبكةٍ عالمية رفيعة المستوى، نحوّل المخاطر الإقليمية\n                المعقّدة إلى فرصٍ منظّمة وآمنة.</span><span class=\"en\">We possess an intimate understanding of the Saudi\n                regulatory environment, regional business dynamics and the unique scale of the Kingdom's transforming\n                economy. By marrying this local expertise with a world-class global network, we translate complex\n                regional risks into structured, secure opportunities.</span></p>\n          </div>\n          <div class=\"val rv\">\n            <div class=\"vn\">04</div>\n            <div>\n              <h3><span class=\"ar\">شراكة متوائمة</span><span class=\"en\">Co-Aligned Partnership</span></h3><span\n                class=\"vq\"><span class=\"ar\">«نوائم رأس المال مع المرونة طويلة الأمد.»</span><span class=\"en\">“Aligning\n                  capital with long-term resilience.”</span></span>\n            </div>\n            <p><span class=\"ar\">نرفض العلاقات العابرة. نعمل امتدادًا استراتيجيًا لشركائنا من مزوّدي الطاقة الاكتتابية،\n                وحليفًا مخلصًا للأسواق المحلية؛ نوظّف طاقتنا الاكتتابية لتعزيز النمو المشترك، ودفع الاستقرار الاقتصادي،\n                وبناء مرونةٍ هيكلية دائمة.</span><span class=\"en\">We reject transactional relationships. We operate as a\n                strategic extension of our capacity partners and a dedicated ally to local markets — deploying our\n                underwriting capacity to foster mutual growth, drive economic stability and build lasting structural\n                resilience.</span></p>\n          </div>\n        </div>\n        <div class=\"promise-box rv\">\n          <svg class=\"pm\" viewBox=\"0 0 543.4 543.4\" aria-hidden=\"true\">\n            <use href=\"#symbol\" />\n          </svg>\n          <div>\n            <h3><span class=\"ar\">وعد العلامة: <em>نرتقي بالطاقة الاكتتابية، ونمكّن النمو الإقليمي.</em></span><span\n                class=\"en\">Brand Promise: <em>Elevating Capacity, Empowering Regional Growth.</em></span></h3>\n            <p><span class=\"ar\">نمدّ الجسر بين الطاقة الاكتتابية العالمية والبصيرة الإقليمية العميقة. ومن قلب الرياض،\n                نمارس الصلاحيات المفوّضة بدقّة محلية، لنقدّم الاستقرار المالي، والمتانة الهيكلية، والذكاء الاكتتابي\n                اللازم لتأمين أكثر آفاق المنطقة طموحًا.</span><span class=\"en\">We bridge global underwriting capacity\n                with deep regional insight. Operating from the heart of Riyadh, we deploy delegated authority with local\n                precision — delivering the financial stability, structural integrity and underwriting intelligence\n                required to secure the region's most ambitious horizons.</span></p>\n          </div>\n        </div>\n      </div>\n    </section><section class=\"closing\" id=\"closing\" data-ch=\"08\" data-ar=\"الختام\" data-en=\"Epilogue\">\n      <div class=\"wrap\" style=\"position:relative\">\n        <div class=\"c-mark\" id=\"cMark\">\n          <svg viewBox=\"-60 -60 663.4 663.4\" aria-hidden=\"true\">\n            <circle class=\"halo\" cx=\"271.06\" cy=\"275.36\" r=\"170\" fill=\"url(#haloG)\" />\n            <g class=\"gA\">\n              <use href=\"#s0\" class=\"o\" />\n              <use href=\"#s1\" class=\"i\" />\n            </g>\n            <g class=\"gB\">\n              <use href=\"#s2\" class=\"o\" />\n              <use href=\"#s3\" class=\"i\" />\n            </g>\n            <use href=\"#star\" class=\"star\" filter=\"url(#glow)\" />\n          </svg>\n        </div>\n        <div class=\"tagline\">\n          <span class=\"rv\"><span class=\"ar\">دقّةٌ في الاكتتاب.</span><span class=\"en\">Precision in\n              Underwriting.</span></span>\n          <span class=\"rv\" style=\"--d:.15s\"><span class=\"ar\">سلطةٌ في الحماية.</span><span class=\"en\">Authority in\n              Protection.</span></span>\n          <span class=\"rv\" style=\"--d:.3s\"><span class=\"ar\">شراكةٌ واسعة النطاق.</span><span class=\"en\">Partnership in\n              Scale.</span></span>\n        </div>\n        <div class=\"c-lock rv\" style=\"--d:.45s\"><svg viewBox=\"0 0 274.81 93.64\">\n            <use href=\"#lockup\" />\n          </svg></div>\n      </div>\n    </section>", "partners": "<section class=\"sec\"><div class=\"wrap\"><div class=\"wr-block\" id=\"who-we-are\">\n          <div class=\"wr-head\">\n            <div class=\"wr-k rv\"><span class=\"l\"></span><span class=\"ar\">من نحن</span><span class=\"en\">Who We Are</span>\n            </div>\n            <h3 class=\"wr-h rv\"><span class=\"ar\">نربط <em>الطاقة الاكتتابية الدولية</em> بالخبرة المحلية</span><span\n                class=\"en\">Connecting <em>global capacity</em> with local expertise</span></h3>\n            <p class=\"lead rv\" style=\"--d:.1s\"><span class=\"ar\">سكاي ري وكيل إعادة تأمين يعمل نيابةً عن معيدي التأمين في\n                الاكتتاب في مخاطر الممتلكات والحوادث التجارية المعقّدة — بما فيها الممتلكات والهندسة والحوادث والطاقة\n                والبحري — فيوزّع المخاطر محليًا بخبرة اكتتابية معزّزة، ويجلب الطاقة الاكتتابية الدولية عبر شبكة\n                متفوّقة.</span><span class=\"en\">SKY RE is a Reinsurance Agent that acts on behalf of Reinsurers to\n                underwrite complex commercial P&amp;C risks — including Property, Engineering, Casualty, Energy and\n                Marine — distributing risks locally through enhanced underwriting expertise, and bringing international\n                capacity through a superior network.</span></p>\n            <ul class=\"wr-sectors rv\" style=\"--d:.18s\">\n              <li><span class=\"ar\">الممتلكات</span><span class=\"en\">Property</span></li>\n              <li><span class=\"ar\">الهندسة</span><span class=\"en\">Engineering</span></li>\n              <li><span class=\"ar\">الحوادث</span><span class=\"en\">Casualty</span></li>\n              <li><span class=\"ar\">الطاقة</span><span class=\"en\">Energy</span></li>\n              <li><span class=\"ar\">البحري</span><span class=\"en\">Marine</span></li>\n            </ul>\n          </div>\n          <div class=\"who-stage rv\" style=\"--d:.1s\" tabindex=\"0\" role=\"img\"\n            aria-label=\"Sky Re connects international reinsurance capacity with local underwriting expertise\">\n            <canvas class=\"who-cv\" aria-hidden=\"true\"></canvas>\n            <svg class=\"who-sym\" viewBox=\"0 0 543.4 543.4\" aria-hidden=\"true\">\n              <g class=\"wA\">\n                <use href=\"#s0\" class=\"o\" />\n                <use href=\"#s1\" class=\"i\" />\n              </g>\n              <g class=\"wB\">\n                <use href=\"#s2\" class=\"o\" />\n                <use href=\"#s3\" class=\"i\" />\n              </g>\n              <use href=\"#star\" class=\"st\" />\n            </svg>\n            <div class=\"who-lab g\"><span class=\"k\">Global</span><span class=\"t\"><span class=\"ar\">الطاقة الاكتتابية\n                  الدولية</span><span class=\"en\">Global Capacity</span></span><span class=\"s\"><span class=\"ar\">معيدو\n                  تأمين دوليون عبر شبكة متفوّقة</span><span class=\"en\">International reinsurers through a superior\n                  network</span></span></div>\n            <div class=\"who-lab l\"><span class=\"k\">Local</span><span class=\"t\"><span class=\"ar\">الخبرة\n                  المحلية</span><span class=\"en\">Local Expertise</span></span><span class=\"s\"><span class=\"ar\">اكتتاب\n                  معزّز وتوزيع للمخاطر في السوق السعودي</span><span class=\"en\">Enhanced underwriting, distributing risk\n                  in the Saudi market</span></span></div>\n            <div class=\"who-lab c\"><b>SKY RE</b><span>MGA</span></div>\n            <p class=\"wr-sr\"><span class=\"ar\">رسم تفاعلي: تتدفّق الطاقة الاكتتابية من معيدي التأمين الدوليين عبر سكاي ري\n                إلى السوق المحلي، وتتدفّق المخاطر في الاتجاه المعاكس.</span><span class=\"en\">Interactive illustration:\n                capacity flows from international reinsurers through Sky Re to the local market, while risk flows in the\n                opposite direction.</span></p>\n          </div>\n          <div class=\"who-cap rv\">\n            <div class=\"lg\"><span><i></i><span class=\"ar\">الطاقة الاكتتابية</span><span\n                  class=\"en\">Capacity</span></span><span><i class=\"s\"></i><span class=\"ar\">المخاطر</span><span\n                  class=\"en\">Risk</span></span></div>\n            <span class=\"hint\"><span class=\"hint-fine\"><span class=\"ar\">حرّك المؤشّر بين الجانبين</span><span\n                  class=\"en\">Move across the two sides</span></span><span class=\"hint-touch\"><span class=\"ar\">مرّر أو\n                  المس الرسم</span><span class=\"en\">Scroll or touch the illustration</span></span></span>\n          </div>\n        </div></div></section>", "loader": "<div id=\"loader\" aria-label=\"Loading\">\n    <div class=\"ld-flare\"></div>\n    <button class=\"ld-skip\" id=\"ldSkip\">Skip ›</button>\n    <div class=\"ld-center\">\n      <svg class=\"ld-mark\" viewBox=\"-40 -40 623.4 623.4\" aria-hidden=\"true\">\n        <circle class=\"ld-halo\" cx=\"271.06\" cy=\"275.36\" r=\"150\" fill=\"url(#haloG)\" />\n        <g class=\"gA\">\n          <use href=\"#s0\" class=\"o\" />\n          <use href=\"#s1\" class=\"i\" />\n        </g>\n        <g class=\"gB\">\n          <use href=\"#s2\" class=\"o\" />\n          <use href=\"#s3\" class=\"i\" />\n        </g>\n        <use href=\"#star\" class=\"ld-star\" filter=\"url(#glow)\" />\n      </svg>\n      <div class=\"ld-word\" style=\"--wm:#f3ead9\">\n        <svg class=\"ld-en\" viewBox=\"0 0 171.54 29.85\">\n          <use href=\"#wm-en\" />\n        </svg>\n        <svg class=\"ld-ar\" viewBox=\"0 48 171.54 30\">\n          <use href=\"#wm-ar\" />\n        </svg>\n      </div>\n    </div>\n    <div class=\"ld-foot\">\n      <div>\n        <div>The Brand Story</div>\n        <div class=\"ar-l\">قصة العلامة</div>\n      </div>\n      <div class=\"ld-pct\" id=\"ldPct\">000</div>\n    </div>\n    <div class=\"ld-bar\"><i id=\"ldBar\"></i></div>\n  </div><div class=\"ld-burst\" id=\"ldBurst\"></div>"};
